mapper.select:
SELECT r.id, r.code, r.member_id, r.seat_id, r.start_time, r.end_time, r.status, r.create_time, m.name AS member_name, m.phone, st.seat_no, st.area FROM reservation r LEFT JOIN member m ON m.id = r.member_id LEFT JOIN seat st ON st.id = r.seat_id
AND r.member_id = #{memberId} AND r.status = #{status}
ORDER BY r.create_time DESC
